2	
3	import (
4		"cmp"
5		"fmt"
6		"strconv"
7		"strings"
8	)
9	
10	type CheckpointFamily string
11	
12	const (
13		CheckpointFamilyBranch CheckpointFamily = "branch"
14		CheckpointFamilyRefs   CheckpointFamily = "refs"
15	)
16	
17	type CheckpointFormat struct {
18		Family CheckpointFamily
19		Major  int
20	}
21	
22	func ParseFormat(raw string) (CheckpointFormat, error) {
23		familyRaw, majorRaw, ok := strings.Cut(raw, "-v")
24		if !ok || familyRaw == "" || majorRaw == "" {
25			return CheckpointFormat{}, fmt.Errorf("invalid checkpoint format %q", raw)
26		}
27	
28		major, err := strconv.Atoi(majorRaw)
29		if err != nil || major <= 0 {
30			return CheckpointFormat{}, fmt.Errorf("invalid checkpoint major %q", majorRaw)
31		}
32	
33		return CheckpointFormat{Family: CheckpointFamily(familyRaw), Major: major}, nil
34	}
35	
36	func (f CheckpointFormat) String() string {
37		if f.Family == "" || f.Major == 0 {
38			return ""
39		}
40		return fmt.Sprintf("%s-v%d", f.Family, f.Major)
41	}
42	
43	func Compare(a, b CheckpointFormat) int {
44		aRank := familyRank(a.Family)
45		bRank := familyRank(b.Family)
46		if aRank != bRank {
47			return cmp.Compare(aRank, bRank)
48		}
49		if a.Family != b.Family {
50			return cmp.Compare(string(a.Family), string(b.Family))
51		}
52		return cmp.Compare(a.Major, b.Major)
53	}
54	
55	func CanRead(format CheckpointFormat) bool {
56		return readFormats[format]
57	}
58	
59	func CanWrite(format CheckpointFormat) bool {
60		return writeFormats[format]
61	}
62	
